(() => {
"use strict";
const CART_KEY = "bc_cart";
const MENU_BURGER_CHOICES = [
"Burger poulet",
"Burger du chef",
"Smash classic",
"Smash double",
"Smash bacon halal",
];
const dialog = document.getElementById("menuBurgerDialog");
const list = document.getElementById("menuBurgerChoices");
const cancel = document.getElementById("menuBurgerCancel");
const readCart = () => {
try {
return JSON.parse(localStorage.getItem(CART_KEY) || "{}") || {};
} catch {
return {};
}
};
const writeCart = (cart) => {
localStorage.setItem(CART_KEY, JSON.stringify(cart));
};
const closeDialog = () => {
if (typeof dialog?.close === "function") dialog.close();
else dialog?.removeAttribute("open");
};
const openDialog = () => {
if (!list) return;
list.innerHTML = MENU_BURGER_CHOICES.map(
(name) =>
`<button type="button" class="menu-choice-btn" data-choice="${name}">${name}</button>`
).join("");
if (typeof dialog?.showModal === "function") dialog.showModal();
else dialog?.setAttribute("open", "");
};
document.addEventListener("click", (e) => {
const menuBtn = e.target.closest("[data-menu-burger]");
if (!menuBtn) return;
e.preventDefault();
openDialog();
});
list?.addEventListener("click", (e) => {
const btn = e.target.closest("[data-choice]");
if (!btn) return;
const cart = readCart();
const key = `menu-burger::${btn.dataset.choice}`;
cart[key] = (cart[key] || 0) + 1;
writeCart(cart);
closeDialog();
window.location.href = "commander.html";
});
cancel?.addEventListener("click", (e) => {
e.preventDefault();
closeDialog();
});
})();
